INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein passiver Tag immer eine Batterie benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Passive Tags nutzen die Energie des Lesegeräts"}, {"text": "Ja", "correct": false, "because": "Nur aktive Tags haben Batterien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frequenz wird typischerweise für kontaktlose Zahlungen genutzt?', 3, '[{"text": "13,56 MHz (HF)", "correct": true, "because": "Standard für NFC und Karten"}, {"text": "125 kHz (LF)", "correct": false, "because": "Für Tierkennzeichnung"}, {"text": "860-960 MHz (UHF)", "correct": false, "because": "Für Logistik"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind für ein Identifikationssystem essenziell?', 5, '[{"text": "Tag", "correct": true, "because": "Speichert Identifikationsdaten"}, {"text": "Lesegerät", "correct": true, "because": "Liest und verarbeitet Daten"}, {"text": "Router", "correct": false, "because": "Für Netzwerk, nicht Identifikation"}, {"text": "Bildschirm", "correct": false, "because": "Nur für Anzeige"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Passive Tags haben keine eigene Stromquelle. b) Sie haben längere Reichweite als aktive Tags.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, aktive Tags haben mehr Reichweite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Systems für die Lagerverwaltung?', 4, '[{"text": "Reichweite der Tags", "correct": false, "because": "Entscheidend für Abdeckung"}, {"text": "Lesegeschwindigkeit", "correct": false, "because": "Beeinflusst Effizienz"}, {"text": "Tag-Farbe", "correct": true, "because": "Kein funktionaler Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Lesegerät Sichtkontakt zum Tag benötigt?', 2, '[{"text": "Nein", "correct": true, "because": "Funktioniert ohne Sichtlinie"}, {"text": "Ja", "correct": false, "because": "Im Gegensatz zu Barcodes"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie verbessert die Bestandskontrolle in einem Lager?', 4, '[{"text": "UHF-Tags", "correct": true, "because": "Große Reichweite für Massenscans"}, {"text": "Infrarotscanner", "correct": false, "because": "Begrenzte Reichweite"}, {"text": "Bluetooth", "correct": false, "because": "Für andere Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass aktive Tags teurer sind als passive. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Wegen Batterie und Reichweite"}, {"text": "Nein", "correct": false, "because": "Passive Tags sind günstiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird ein chipless Tag wie ein chipped Tag gelesen?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzt andere Codierungsmethoden"}, {"text": "Ja", "correct": false, "because": "Chipless ohne Mikrochip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Lesereichweite eines Systems?', 5, '[{"text": "Frequenzband", "correct": true, "because": "HF, UHF, LF unterschiedlich"}, {"text": "Tag-Typ", "correct": true, "because": "Aktiv oder passiv"}, {"text": "Routergeschwindigkeit", "correct": false, "because": "Kein Einfluss"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung eines Systems für Zutrittskontrolle?', 4, '[{"text": "Schnelle Lesezeit", "correct": true, "because": "Vermeidet Wartezeiten"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Sekundär für Zutritt"}, {"text": "Visuelles Design", "correct": false, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UHF-Tags haben eine größere Reichweite als HF. b) Sie sind besser für Metallumgebungen geeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, HF besser bei Metall"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein System zur Tierkennzeichnung?', 3, '[{"text": "LF-Tags", "correct": false, "because": "Standard für Tiere"}, {"text": "Lesegerät", "correct": false, "because": "Notwendig zum Auslesen"}, {"text": "Grafikkarte", "correct": true, "because": "Kein Einfluss auf Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich ein System für die Logistik einrichte?', 4, '[{"text": "UHF-Tags und Lesegeräte installieren", "correct": true, "because": "Große Reichweite für Paletten"}, {"text": "Nur Barcodes nutzen", "correct": false, "because": "Sichtkontakt nötig"}, {"text": "HF-Tags für große Distanzen", "correct": false, "because": "HF hat geringere Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Metall die Funksignale stört. Stimmt das?', 3, '[{"text": "Ja", "correct": true, "because": "Metall reflektiert Signale"}, {"text": "Nein", "correct": false, "because": "Beeinträchtigung ist bekannt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll hilft, Kollisionen mehrerer Tags zu vermeiden?', 4, '[{"text": "Anti-Kollisionsprotokoll", "correct": true, "because": "Regelt gleichzeitige Lesevorgänge"}, {"text": "FTP-Protokoll", "correct": false, "because": "Für Dateitransfer"}, {"text": "HTTP-Protokoll", "correct": false, "because": "Für Web"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Funktioniert ein System auch bei Flüssigkeiten?', 2, '[{"text": "Ja", "correct": true, "because": "HF-Tags funktionieren bei Flüssigkeiten"}, {"text": "Nein", "correct": false, "because": "Nur teilweise beeinträchtigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein System für die Bestandskontrolle?', 5, '[{"text": "Echtzeit-Tracking", "correct": true, "because": "Aktuelle Bestände sichtbar"}, {"text": "Reduzierte Fehler", "correct": true, "because": "Automatische Erfassung"}, {"text": "Schnellere Installation", "correct": false, "because": "Kein primärer Vorteil"}, {"text": "Bessere Grafik", "correct": false, "because": "Kein funktionaler Nutzen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl eines Systems für ein Krankenhaus unwichtig?', 3, '[{"text": "Datensicherheit", "correct": false, "because": "Schützt Patientendaten"}, {"text": "Lesegenauigkeit", "correct": false, "because": "Sichert korrekte Identifikation"}, {"text": "Tag-Design", "correct": true, "because": "Kosmetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Tags für kontaktlose Zahlungen einrichte?', 4, '[{"text": "HF-Tags mit NFC nutzen", "correct": true, "because": "Standard für kurze Distanzen"}, {"text": "UHF-Tags einsetzen", "correct": false, "because": "Zu große Reichweite"}, {"text": "Ohne Lesegerät arbeiten", "correct": false, "because": "Lesegerät nötig"}]');
